head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > E > onchange]<br/>Multiselect 컴포넌트에서 아이템의 선택이 변경되면 발생합니다.",
    "validation" : [
        "Multiselect 컴포넌트에서 아이템의 선택이 변경되면 발생합니다.",
        "사용자의 조작에 의해 기존과 동일한 아이템을 선택한 경우엔 onchange 이벤트가 발생합니다.",
        "이벤트 핸들러에 파라미터가 없으므로, 변경된 값이 필요하면 getValue(), getText(), getSelectedIndex() 등의 메소드를 직접 실행해야 합니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// onchange 이벤트 핸들러 — multiselect onchange 는 파라미터 없음 (engine spec)
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};



// onviewchange 이벤트 핸들러 — onchange 와 차이 비교용
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : [" + (info ? info.oldValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : [" + (info ? info.newValue : "") + "]");
};



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cList = $c.gcm.createCList({ separator: "," });
    let eHandler = 'ev:onchange="scwin.target1_onchange" ev:onviewchange="scwin.target1_onviewchange"';

    await $c.gcm.createBasicMultiSelect(cList, eHandler);
}



// 결과 확인 - getValue / getText / getSelectedIndex 직접 호출 (핸들러 파라미터 없음 검증)
scwin.btn_getResult_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};
